parameters.jsCode:
// 1. Extract payload safely from body or root
const raw = $json.body || $json;

// 2. Validate mandatory envelope fields
if (!raw || typeof raw !== 'object') {
  throw new Error('Validation Error: Empty or non-object request body.');
}

const eventId = raw.eventId;
const eventType = raw.eventType;

if (!eventId || typeof eventId !== 'string') {
  throw new Error('Validation Error: Missing or invalid eventId.');
}

const allowedTypes = [
  'booking.confirmed',
  'ticket.exchange.completed',
  'ticket.refund.completed',
  'ticket.checked_in'
];

if (!allowedTypes.includes(eventType)) {
  throw new Error(`Validation Error: Unsupported eventType: ${eventType}`);
}

// 3. Idempotency Check using n8n Workflow Static Data
const staticData = $getWorkflowStaticData('global');
staticData.processedEvents = staticData.processedEvents || {};

// Clean up keys older than 7 days (604800000 ms)
const now = Date.now();
for (const id in staticData.processedEvents) {
  if (now - staticData.processedEvents[id] > 604800000) {
    delete staticData.processedEvents[id];
  }
}

if (staticData.processedEvents[eventId]) {
  return [{
    json: {
      ...raw,
      isDuplicate: true,
      processedAt: new Date(staticData.processedEvents[eventId]).toISOString()
    }
  }];
}

// Record eventId as processed
staticData.processedEvents[eventId] = now;

return [{
  json: {
    ...raw,
    isDuplicate: false,
    receivedAt: new Date().toISOString()
  }
}];

const ev = $json;
const customer = ev.customer || {};
const movie = ev.movie || {};
const show = ev.showtime || {};
const booking = ev.booking || {};
const seats = Array.isArray(ev.seats) ? ev.seats : [];
const combos = Array.isArray(ev.combos) ? ev.combos : [];

const recipientEmail = ev.recipientEmail || customer.email;
if (!recipientEmail) {
  throw new Error('Notification Error: recipientEmail is missing for booking.confirmed.');
}

const formattedTotal = Number(booking.total || 0).toLocaleString('vi-VN') + ' VND';
const formattedTime = show.startsAt ? new Date(show.startsAt).toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }) : 'Đang cập nhật';

const combosHtml = combos.length > 0
  ? `<ul style="margin: 6px 0; padding-left: 20px;">${combos.map(c => `<li>${c.name} x ${c.quantity} (${Number(c.unitPrice || 0).toLocaleString('vi-VN')} VND)</li>`).join('')}</ul>`
  : '<p style="color: #9ca3af; margin: 4px 0;">Không kèm bắp nước</p>';

const html = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 620px; margin: auto; padding: 24px; background-color: #0b0f19; color: #f3f4f6; border-radius: 12px; border: 1px solid #1f2937;">
  <div style="text-align: center; border-bottom: 2px solid #fbbf24; padding-bottom: 16px; margin-bottom: 20px;">
    <h1 style="color: #fbbf24; margin: 0; font-size: 24px; letter-spacing: 1px;">✨ STARLIGHT CINEMA ✨</h1>
    <p style="color: #9ca3af; margin: 6px 0 0 0; font-size: 14px;">Xác nhận đặt vé xem phim thành công</p>
  </div>

  <p style="font-size: 15px;">Kính chào <strong>${customer.name || customer.email || 'Quý khách'}</strong>,</p>
  <p style="font-size: 14px; line-height: 1.6; color: #d1d5db;">Đơn hàng của bạn đã được thanh toán và xác nhận thành công trên hệ thống Starlight Cinema. Dưới đây là thông tin chi tiết vé xem phim của bạn:</p>

  <div style="background-color: #111827; border: 1px solid #374151; border-radius: 8px; padding: 18px; margin: 20px 0;">
    <p style="margin: 8px 0; font-size: 15px;">🎬 <strong>Phim:</strong> <span style="color: #60a5fa; font-weight: bold;">${movie.title || 'Phim chiếu rạp'}</span></p>
    <p style="margin: 8px 0;">🏛️ <strong>Rạp chiếu:</strong> ${show.cinema || 'Starlight Cinema'}</p>
    <p style="margin: 8px 0;">🚪 <strong>Phòng chiếu:</strong> ${show.room || 'Phòng chiếu'}</p>
    <p style="margin: 8px 0;">⏰ <strong>Suất chiếu:</strong> <span style="color: #34d399; font-weight: bold;">${formattedTime}</span></p>
    <p style="margin: 8px 0;">💺 <strong>Ghế đã đặt:</strong> <strong style="color: #f59e0b; font-size: 16px;">${seats.join(', ') || 'N/A'}</strong></p>
    <p style="margin: 8px 0;">🧾 <strong>Mã đơn hàng:</strong> <code style="background: #1f2937; padding: 2px 6px; border-radius: 4px; color: #e5e7eb;">${booking.id || 'N/A'}</code></p>
    <p style="margin: 8px 0;">💰 <strong>Tổng thanh toán:</strong> <strong style="color: #fbbf24; font-size: 16px;">${formattedTotal}</strong></p>
  </div>

  <div style="background-color: #111827; border: 1px solid #374151; border-radius: 8px; padding: 14px 18px; margin: 16px 0;">
    <h4 style="color: #e5e7eb; margin: 0 0 8px 0; font-size: 14px;">🍿 Bắp nước & Combo kèm theo:</h4>
    ${combosHtml}
  </div>

  <div style="background-color: #1e1b4b; border-left: 4px solid #818cf8; padding: 14px; border-radius: 4px; margin: 20px 0;">
    <p style="margin: 0; font-size: 13px; line-height: 1.5; color: #c7d2fe;">
      🎟️ <strong>Hướng dẫn nhận vé:</strong> Vui lòng truy cập website Starlight Cinema, vào mục <strong>Vé của tôi</strong> để lấy mã QR điện tử. Xuất trình mã QR tại cửa soát vé trước giờ chiếu ít nhất 15 phút.
    </p>
  </div>

  <p style="color: #6b7280; font-size: 12px; text-align: center; margin-top: 28px; border-top: 1px solid #1f2937; padding-top: 12px;">
    Hệ thống thông báo tự động từ Starlight Cinema • Email được gửi qua dịch vụ Gmail SMTP chính thức.
  </p>
</div>
`;

return [{
  json: {
    recipientEmail,
    subject: `[Starlight Cinema] Xác nhận đặt vé thành công: ${movie.title || 'Vé xem phim'}`,
    htmlText: html,
    eventId: ev.eventId,
    eventType: ev.eventType
  }
}];

const ev = $json;
const exchange = ev.exchange || {};
const oldTickets = Array.isArray(exchange.oldTickets) ? exchange.oldTickets : [];
const newTickets = Array.isArray(exchange.newTickets) ? exchange.newTickets : [];
const recipientEmail = ev.recipientEmail || (ev.customer && ev.customer.email);

if (!recipientEmail) {
  throw new Error('Notification Error: recipientEmail is missing for ticket.exchange.completed.');
}

const payableText = exchange.payable ? `${Number(exchange.payable).toLocaleString('vi-VN')} VND` : '0 VND';

const html = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 620px; margin: auto; padding: 24px; background-color: #0b0f19; color: #f3f4f6; border-radius: 12px; border: 1px solid #1f2937;">
  <div style="text-align: center; border-bottom: 2px solid #3b82f6; padding-bottom: 16px; margin-bottom: 20px;">
    <h1 style="color: #3b82f6; margin: 0; font-size: 24px;">🔄 STARLIGHT CINEMA</h1>
    <p style="color: #9ca3af; margin: 6px 0 0 0;">Thông báo xác nhận đổi vé thành công</p>
  </div>

  <p style="font-size: 15px;">Kính chào Quý khách,</p>
  <p style="font-size: 14px; line-height: 1.6; color: #d1d5db;">Yêu cầu đổi vé xem phim của bạn đã được nhân viên quầy xử lý và phê duyệt hoàn tất theo chính sách:</p>

  <div style="background-color: #111827; border: 1px solid #374151; border-radius: 8px; padding: 18px; margin: 20px 0;">
    <p style="margin: 8px 0;">📋 <strong>Mã yêu cầu đổi vé:</strong> <code style="background: #1f2937; padding: 2px 6px; border-radius: 4px; color: #e5e7eb;">${exchange.requestId || 'N/A'}</code></p>
    <p style="margin: 8px 0;">🎟️ <strong>Số lượng vé đã đổi:</strong> ${newTickets.length} vé</p>
    <p style="margin: 8px 0;">💺 <strong>Vị trí ghế mới:</strong> <strong style="color: #34d399;">${newTickets.map(t => t.seatLabel || t.id).join(', ')}</strong></p>
    <p style="margin: 8px 0;">💳 <strong>Khoản chênh lệch đã thanh toán:</strong> ${payableText}</p>
  </div>

  <div style="background-color: #1e1b4b; border-left: 4px solid #60a5fa; padding: 14px; border-radius: 4px; margin: 20px 0;">
    <p style="margin: 0; font-size: 13px; color: #bfdbfe;">
      📌 <strong>Lưu ý:</strong> Toàn bộ vé cũ đã được thu hồi và chuyển trạng thái <code>REPLACED</code>. Vui lòng mở mục <strong>Vé của tôi</strong> để xuất trình vé mới khi check-in.
    </p>
  </div>
</div>
`;

return [{
  json: {
    recipientEmail,
    subject: `[Starlight Cinema] Xác nhận hoàn tất đổi vé #${exchange.requestId || ''}`,
    htmlText: html,
    eventId: ev.eventId,
    eventType: ev.eventType
  }
}];

const ev = $json;
const refund = ev.refund || {};
const recipientEmail = ev.recipientEmail || (ev.customer && ev.customer.email);

if (!recipientEmail) {
  throw new Error('Notification Error: recipientEmail is missing for ticket.refund.completed.');
}

const amountText = refund.amount ? `${Number(refund.amount).toLocaleString('vi-VN')} VND` : '0 VND';

const html = `
<div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; max-width: 620px; margin: auto; padding: 24px; background-color: #0b0f19; color: #f3f4f6; border-radius: 12px; border: 1px solid #1f2937;">
  <div style="text-align: center; border-bottom: 2px solid #ef4444; padding-bottom: 16px; margin-bottom: 20px;">
    <h1 style="color: #ef4444; margin: 0; font-size: 24px;">💸 STARLIGHT CINEMA</h1>
    <p style="color: #9ca3af; margin: 6px 0 0 0;">Thông báo hoàn tất hoàn tiền vé</p>
  </div>

  <p style="font-size: 15px;">Kính chào Quý khách,</p>
  <p style="font-size: 14px; line-height: 1.6; color: #d1d5db;">Giao dịch hoàn tiền cho vé xem phim của bạn đã được đối soát và xử lý thành công:</p>

  <div style="background-color: #111827; border: 1px solid #374151; border-radius: 8px; padding: 18px; margin: 20px 0;">
    <p style="margin: 8px 0;">📋 <strong>Mã yêu cầu hoàn vé:</strong> <code style="background: #1f2937; padding: 2px 6px; border-radius: 4px; color: #e5e7eb;">${refund.requestId || 'N/A'}</code></p>
    <p style="margin: 8px 0;">💵 <strong>Số tiền hoàn trả:</strong> <strong style="color: #fbbf24; font-size: 16px;">${amountText}</strong></p>
    ${refund.reason ? `<p style="margin: 8px 0;">📝 <strong>Lý do hoàn:</strong> ${refund.reason}</p>` : ''}
  </div>

  <p style="font-size: 13px; color: #9ca3af;">Số tiền hoàn sẽ được hoàn về phương thức thanh toán ban đầu của quý khách theo thời gian quy định của đơn vị cung cấp.</p>
</div>
`;

return [{
  json: {
    recipientEmail,
    subject: `[Starlight Cinema] Xác nhận hoàn tiền thành công #${refund.requestId || ''}`,
    htmlText: html,
    eventId: ev.eventId,
    eventType: ev.eventType
  }
}];

const ev = $json;
const checkIn = ev.checkIn || {};

// Acknowledge check-in event received by workflow automation.
// Actual persistence is already committed in the Backend's check_ins & audit_logs tables.
return [{
  json: {
    status: 'ACKNOWLEDGED',
    eventType: 'ticket.checked_in',
    eventId: ev.eventId,
    ticketId: checkIn.ticketId || null,
    checkedInAt: checkIn.checkedInAt || null,
    staffId: checkIn.staffId || null,
    message: 'Check-in event acknowledged by n8n automation; verified from backend audit log; no customer notification email required.'
  }
}];

